param($Request,$TriggerMetadata)
. "$PSScriptRoot\..\shared\Storage.ps1"
try{$table=Get-TableHandle $env:CERTAMENT_LATEST_TABLE;$rows=@(Get-AzTableRow -table $table);$critical=@($rows|Where-Object Status -eq 'Critical').Count;$warning=@($rows|Where-Object Status -eq 'Warning').Count;$status=if($critical -gt 0){'Critical'}elseif($warning -gt 0){'Warning'}else{'Healthy'};Push-OutputBinding -Name Response -Value (New-MonitoringResponse 200 @{status=$status;servers=$rows.Count;critical=$critical;warning=$warning;timestampUtc=[DateTime]::UtcNow.ToString('o')})}catch{Write-Error $_;Push-OutputBinding -Name Response -Value (New-MonitoringResponse 500 @{status='Critical';error='Storage operation failed.'})}
